package za.co.mamadise.support_ticket_tracker.attachment;

import java.io.IOException;
import java.io.InputStream;

/**
 * Where attachment bytes live. Keys are generated by the server (random UUIDs); implementations must never accept
 * a key that could address anything outside their own storage. Swap the bean for object storage (S3 etc.) later.
 */
public interface AttachmentStorage {

    void store(String key, byte[] content) throws IOException;

    InputStream open(String key) throws IOException;

    /** Removes the file if it exists; never fails because it is already gone. */
    void delete(String key) throws IOException;
}
